<script setup lang="ts">
import gsap from "gsap";
const svg = ref<HTMLElement>();
let tl: gsap.core.Timeline;
let ctx: gsap.Context;

onMounted(() => {
  ctx = gsap.context((self) => {
    if (!self.selector) return;
    const elements = self.selector(".bar");

    tl = gsap.timeline({
      scrollTrigger: {
        trigger: svg.value,
        start: "top 40%",
        end: "bottom 45%",
        scrub: true,
        // markers: true,
      },
    });

    tl.fromTo(
      elements,
      {
        scaleY: 0,
        transformOrigin: "bottom",
      },
      {
        scaleY: 1,
        stagger: {
          amount: 0.55,
        },
      },
    );
  }, svg.value);
});

onUnmounted(() => {
  ctx.revert();
});
</script>
